-- rowstile 0.1.0-dev: keys_and_requests_go_with_their_rows. Generated by rowstile migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the same policy; what rowstile makes of it changed

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', '4ba25137a71fd47a', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '4ba25137a71fd47a' THEN
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '4ba25137a71fd47a' THEN
    RAISE EXCEPTION 'rowstile: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only from here on; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_attribute
             WHERE attrelid = to_regclass('authz.policy_versions') AND attname = 'lock' AND NOT attisdropped) THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock = '4ba25137a71fd47a' THEN
    RAISE EXCEPTION 'rowstile: this database already holds what this migration brings (it ran here before, or rowstile dev or push took the database there): don''t run it, tell your migration tool it is applied [AZ607]'
      USING HINT = 'Prisma: prisma migrate resolve --applied <the migration''s folder>. Alembic: alembic stamp head. '
                   'Others, and why: rowstile help AZ607';
  ELSIF v_lock IS DISTINCT FROM 'a43aabf020ce6317' THEN
    RAISE EXCEPTION 'rowstile: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      'a43aabf020ce6317', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowstile push or apply since needs the '
                   'migrations from the start (or rowstile apply of the policy the previous migration left) '
                   '(rowstile help AZ607)';
  END IF;
END $authz_guard$;

-- the row triggers given to tables that inherit: made again below, on what this migration makes
DO $authz_ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT g.tgname, g.tgrelid::regclass AS tbl FROM pg_catalog.pg_trigger g
           JOIN pg_catalog.pg_description d ON d.objoid = g.oid AND d.classoid = 'pg_catalog.pg_trigger'::regclass
           WHERE d.description = 'rowstile: the trigger of the table above, for the rows stored here' LOOP
    EXECUTE pg_catalog.format('DROP TRIGGER %I ON %s', r.tgname, r.tbl);
  END LOOP;
END $authz_ch$;

-- what goes, or is made again
DROP FUNCTION IF EXISTS
  authz_int.mark_shared(p_type text, p_id text);
DROP TABLE IF EXISTS
  authz_int.share_marks;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

-- a row for each row a share, a key or a request named (authz_int.mark_row), until that row is gone
CREATE TABLE authz_int.row_marks (type text, id text, n bigint NOT NULL DEFAULT 0, PRIMARY KEY (type, id));

DO $r$ BEGIN PERFORM set_config('authz_ctx.reason', 'applying the policy: the row was deleted', true); END $r$;

-- Shares stored with ids that aren't canonical ('007', an uppercase uuid: written directly before every
-- write went through authz_int.canon) are made canonical, since the sweep below and the triggers compare
-- text; one that then repeats a share already stored goes, the first made staying
CREATE TEMP TABLE authz_uncanonical ON COMMIT DROP AS
  SELECT g.ctid AS row, authz_int.canon(g.object_type, g.object_id) AS object_id,
         authz_int.canon(g.subject_type, g.subject_id) AS subject_id
  FROM authz.shares g
  WHERE g.object_id IS DISTINCT FROM authz_int.canon(g.object_type, g.object_id)
     OR g.subject_id IS DISTINCT FROM authz_int.canon(g.subject_type, g.subject_id);
DELETE FROM authz.shares g USING authz_uncanonical u
WHERE g.ctid = u.row AND EXISTS (
  SELECT 1 FROM authz.shares c WHERE c.object_type = g.object_type AND c.object_id = u.object_id AND c.relation = g.relation
    AND c.subject_type = g.subject_type AND c.subject_id = u.subject_id AND c.subject_relation = g.subject_relation);
DELETE FROM authz.shares g USING (
  SELECT u.row, row_number() OVER (PARTITION BY s.object_type, u.object_id, s.relation, s.subject_type, u.subject_id,
                                   s.subject_relation ORDER BY s.created_at, u.row) AS n
  FROM authz_uncanonical u JOIN authz.shares s ON s.ctid = u.row) d
WHERE g.ctid = d.row AND d.n > 1;
UPDATE authz.shares g SET object_id = u.object_id, subject_id = u.subject_id FROM authz_uncanonical u WHERE g.ctid = u.row;
DROP TABLE authz_uncanonical;

-- Shares on rows that no longer exist (deleted while no trigger watched them) are dropped
DELETE FROM authz.shares g WHERE g.object_type = 'user' AND NOT EXISTS (SELECT 1 FROM "ms"."users" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'user' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "ms"."users" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'bot' AND NOT EXISTS (SELECT 1 FROM "ms"."bots" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'bot' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "ms"."bots" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'chat' AND NOT EXISTS (SELECT 1 FROM "ms"."chats" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'chat' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "ms"."chats" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'membership' AND NOT EXISTS (SELECT 1 FROM "ms"."members" x WHERE ROW(x."chat_id"::bigint, x."user_id"::uuid)::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'membership' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "ms"."members" x WHERE ROW(x."chat_id"::bigint, x."user_id"::uuid)::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'message' AND NOT EXISTS (SELECT 1 FROM "ms"."messages" x WHERE ROW(x."chat_id"::bigint, x."seq"::bigint)::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'message' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "ms"."messages" x WHERE ROW(x."chat_id"::bigint, x."seq"::bigint)::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'chat_bot' AND NOT EXISTS (SELECT 1 FROM "ms"."chat_bots" x WHERE ROW(x."chat_id"::bigint, x."bot_id"::bigint)::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'chat_bot' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "ms"."chat_bots" x WHERE ROW(x."chat_id"::bigint, x."bot_id"::bigint)::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'block' AND NOT EXISTS (SELECT 1 FROM "ms"."blocks" x WHERE ROW(x."blocker_id"::uuid, x."blocked_id"::uuid)::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'block' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "ms"."blocks" x WHERE ROW(x."blocker_id"::uuid, x."blocked_id"::uuid)::text = g.subject_id);
-- ...and so are the API keys of principals that no longer exist
DELETE FROM authz.api_keys k WHERE k.principal_type = 'user' AND NOT EXISTS (SELECT 1 FROM "ms"."users" x WHERE x."id"::text = k.user_id);
DELETE FROM authz.api_keys k WHERE k.principal_type = 'bot' AND NOT EXISTS (SELECT 1 FROM "ms"."bots" x WHERE x."id"::text = k.user_id);
-- ...and pending access requests whose requester no longer exists are cancelled (not those whose object
-- doesn't: a request for a missing object is allowed, so that asking doesn't tell which hidden ones exist)
UPDATE authz.requests r SET status = 'cancelled', decided_at = now(), note = 'its requester is gone' WHERE r.status = 'pending' AND NOT EXISTS (SELECT 1 FROM "ms"."users" x WHERE x."id"::text = r.requester);

DO $r$ BEGIN PERFORM set_config('authz_ctx.reason', '', true); END $r$;

-- a share, a key or a request naming a row marks it (a new version of its mark, which a transaction that can't
-- see it and then deletes the row, or changes its id, writes too: forget_marks)
CREATE FUNCTION authz_int.mark_row(p_type text, p_id text) RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  INSERT INTO authz_int.row_marks AS m (type, id) VALUES (p_type, p_id)
  ON CONFLICT (type, id) DO UPDATE SET n = m.n + 1 $f$;

-- rows that are gone, or whose id changed: their marks go too. In a transaction whose snapshot may be older than a
-- share, key or request naming one of them (not READ COMMITTED), the marks are written first: if one was made since,
-- that fails to serialize (40001), rather than leave what the deletes after can't see
CREATE OR REPLACE FUNCTION authz_int.forget_marks(p_type text, p_ids text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF pg_catalog.current_setting('transaction_isolation') <> 'read committed' THEN
    INSERT INTO authz_int.row_marks AS m (type, id) SELECT DISTINCT p_type, x FROM unnest(p_ids) x
    ON CONFLICT (type, id) DO UPDATE SET n = m.n + 1;
  END IF;
  DELETE FROM authz_int.row_marks WHERE type = p_type AND id = ANY (p_ids);
END $f$;

-- shares on chat rows that are gone, or whose id changed, are removed (and their marks: forget_marks), and
-- the pending requests naming them are cancelled (requests_gone)
CREATE OR REPLACE FUNCTION authz_int."chat__forget"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF TG_OP = 'TRUNCATE' THEN
    DELETE FROM authz.shares WHERE object_type = 'chat';
    DELETE FROM authz.shares WHERE subject_type = 'chat' AND subject_id <> '*';      -- '*' (every one signed in) names no row
    DELETE FROM authz_int.row_marks WHERE type = 'chat';
    PERFORM authz_int.requests_gone('chat', NULL);
  ELSIF TG_OP = 'UPDATE' THEN   -- on a partitioned table (the last trigger below): the ids the update left no row with
    PERFORM authz_int.forget_marks('chat', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
    DELETE FROM authz.shares WHERE object_type = 'chat' AND object_id IN (SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n);
    DELETE FROM authz.shares WHERE subject_type = 'chat' AND subject_id IN (SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n);
    PERFORM authz_int.requests_gone('chat', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
  ELSE
    PERFORM authz_int.forget_marks('chat', ARRAY(SELECT o."id"::text FROM old_rows o));
    DELETE FROM authz.shares WHERE object_type = 'chat' AND object_id IN (SELECT o."id"::text FROM old_rows o);
    DELETE FROM authz.shares WHERE subject_type = 'chat' AND subject_id IN (SELECT o."id"::text FROM old_rows o);
    PERFORM authz_int.requests_gone('chat', ARRAY(SELECT o."id"::text FROM old_rows o));
  END IF;
  RETURN NULL;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."chat__forget_id"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  PERFORM authz_int.forget_marks('chat', ARRAY[OLD."id"::text]);
  DELETE FROM authz.shares WHERE object_type = 'chat' AND object_id = OLD."id"::text;
  DELETE FROM authz.shares WHERE subject_type = 'chat' AND subject_id = OLD."id"::text;
  PERFORM authz_int.requests_gone('chat', ARRAY[OLD."id"::text]);
  RETURN NULL;
END $f$;

-- Share: needs the relation's 'shared by' permission on the object, and every permission
-- the relation grants (you can't grant more than you hold); the subject must exist
CREATE OR REPLACE FUNCTION authz.share(p_type text, p_id text, p_relation text,
  p_subject_type text, p_subject_id text, p_subject_relation text DEFAULT '',
  p_expires_at timestamptz DEFAULT NULL, p_starts_at timestamptz DEFAULT NULL,
  p_caveat text DEFAULT NULL, p_caveat_args jsonb DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_tbl text; v_find text; v_found boolean; v_key text; v_rel authz_int.shared_relations; v_need text;
        v_role authz.roles;
BEGIN
  PERFORM authz_int.check_writable();
  p_id := authz_int.canon(p_type, p_id);
  p_subject_id := authz_int.canon(p_subject_type, p_subject_id);
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- lock the object (FOR KEY SHARE): a concurrent delete waits for us, or we for it
  SELECT t.tbl, t.find INTO v_tbl, v_find FROM authz_int.types t WHERE t.name = p_type;
  IF v_tbl IS NULL THEN RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707'; END IF;
  IF NOT pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)) THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s x WHERE %s FOR KEY SHARE)', v_tbl, v_find) INTO v_found USING p_id;
  -- a caller who may share nothing on the object gets the answer a missing object gets (this same RAISE),
  -- before the subject and the relation are looked at: sharing never tells a hidden object from a missing one
  v_found := v_found AND EXISTS (
    SELECT 1 FROM (SELECT s.shared_by AS perm FROM authz_int.shared_relations s WHERE s.object_type = p_type
                   UNION SELECT 'share') x
    -- (CASE: authz.can raises for a permission the type doesn't have, and AND doesn't say which runs first)
    WHERE CASE WHEN EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = x.perm)
               THEN authz.can(p_type, p_id, x.perm) ELSE false END);
  IF NOT v_found THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  v_key := CASE WHEN p_subject_type IN ('anyone', 'link') THEN p_subject_type
                WHEN p_subject_id = '*' AND p_subject_relation = '' THEN p_subject_type || ':*'
                WHEN p_subject_relation <> '' THEN p_subject_type || '#' || p_subject_relation
                ELSE p_subject_type END;
  -- the subject must exist (and is locked, like the object)
  IF v_key NOT LIKE '%:*' AND v_key NOT IN ('anyone', 'link') THEN
    SELECT t.tbl, t.find INTO v_tbl, v_find FROM authz_int.types t WHERE t.name = p_subject_type;
    v_found := v_tbl IS NOT NULL AND pg_catalog.pg_input_is_valid(p_subject_id,
                 (SELECT keytype FROM authz_int.types WHERE name = p_subject_type));
    IF v_found THEN
      EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s x WHERE %s FOR KEY SHARE)', v_tbl, v_find)
        INTO v_found USING p_subject_id;
    END IF;
    IF NOT v_found THEN
      RAISE EXCEPTION 'there is no % %', p_subject_type, p_subject_id USING HINT = 'rowstile help AZ708';
    END IF;
  END IF;
  IF p_relation LIKE 'role:%' THEN
    -- a custom role: its type must match, the subject must be allowed, and you must hold all it grants
    SELECT * INTO v_role FROM authz.roles WHERE 'role:' || id = p_relation;
    IF v_role.id IS NULL OR v_role.object_type <> p_type THEN
      RAISE EXCEPTION 'no role % for %', p_relation, p_type USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT authz_int.role_owned(p_type, p_id, v_role.owner_type, v_role.owner_id) THEN
      RAISE EXCEPTION 'role % belongs to % %, which doesn''t own % %', v_role.name, v_role.owner_type, v_role.owner_id,
        p_type, p_id USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.role_subjects WHERE object_type = p_type AND subject = v_key) THEN
      RAISE EXCEPTION 'custom roles on % cannot be given to %', p_type, v_key USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = 'share')
       OR NOT authz.can(p_type, p_id, 'share') THEN
      RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
    SELECT string_agg(permission, ', ') INTO v_need FROM authz.role_permissions
    WHERE role_id = v_role.id AND NOT authz.can(p_type, p_id, permission);
    IF v_need IS NOT NULL THEN
      RAISE EXCEPTION 'you cannot give role % on % %: you do not hold %', v_role.name, p_type, p_id, v_need
        USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
  ELSE
    SELECT * INTO v_rel FROM authz_int.shared_relations s
    WHERE s.object_type = p_type AND s.relation = p_relation AND s.subject = v_key;
    IF v_rel.relation IS NULL THEN
      RAISE EXCEPTION 'the policy does not allow sharing %.% with %', p_type, p_relation, v_key USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = v_rel.shared_by)
       OR NOT authz.can(p_type, p_id, v_rel.shared_by) THEN
      RAISE EXCEPTION 'you cannot share % % (needs %)', p_type, p_id, v_rel.shared_by USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
    SELECT string_agg(n, ', ') INTO v_need FROM unnest(v_rel.required) n WHERE NOT authz.can(p_type, p_id, n);
    IF v_need IS NOT NULL THEN
      RAISE EXCEPTION 'you cannot grant %.% on % %: you do not hold %', p_type, p_relation, p_type, p_id, v_need
        USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
    IF NOT authz_int.share_if(p_type || '.' || p_relation || '.' || v_key, p_id, p_subject_type,
                              p_subject_id, p_subject_relation) THEN
      RAISE EXCEPTION 'the policy does not allow this share (%)', coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = v_rel.loc), '?') USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
  END IF;
  IF p_caveat IS NOT NULL AND NOT EXISTS (SELECT 1 FROM authz_int.caveats WHERE name = p_caveat) THEN
    RAISE EXCEPTION 'no caveat % in the policy', p_caveat USING HINT = 'rowstile help AZ707';
  END IF;
  PERFORM authz_int.mark_row(p_type, p_id);
  IF v_key NOT LIKE '%:*' AND v_key NOT IN ('anyone', 'link') THEN
    PERFORM authz_int.mark_row(p_subject_type, p_subject_id);
  END IF;
  INSERT INTO authz.shares (object_type, object_id, relation, subject_type, subject_id, subject_relation,
                            expires_at, created_by, starts_at, caveat, caveat_args)
  VALUES (p_type, p_id, p_relation, p_subject_type, p_subject_id, p_subject_relation,
          p_expires_at, authz_int.actor(), p_starts_at, p_caveat, p_caveat_args)
  ON CONFLICT ON CONSTRAINT shares_pkey
  DO UPDATE SET expires_at = EXCLUDED.expires_at, created_by = EXCLUDED.created_by,
                starts_at = EXCLUDED.starts_at, caveat = EXCLUDED.caveat, caveat_args = EXCLUDED.caveat_args;
END $f$;

-- the keys of principals that are gone, or whose id changed (p_ids; NULL: every one of the type, TRUNCATE) are
-- deleted, each in the audit trail, with the rows' marks (forget_marks: in a transaction whose snapshot may be older
-- than a key made for one of them, that fails to serialize, 40001)
CREATE FUNCTION authz_int.keys_gone(p_type text, p_ids text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k record;
BEGIN
  IF p_ids IS NULL THEN
    DELETE FROM authz_int.row_marks WHERE type = p_type;
  ELSE
    PERFORM authz_int.forget_marks(p_type, p_ids);
  END IF;
  FOR k IN DELETE FROM authz.api_keys WHERE principal_type = p_type AND (p_ids IS NULL OR user_id = ANY (p_ids))
           RETURNING id, user_id, name LOOP
    PERFORM authz_int.audit('delete_api_key', p_type, k.user_id, NULL, NULL, NULL, NULL,
                            jsonb_build_object('key', k.id, 'name', k.name, 'why', 'its principal is gone'));
  END LOOP;
END $f$;

-- API keys: a signed-in user's own, or a principal's (a service's) made by someone holding
-- manage_keys on it; only a hash is kept
CREATE OR REPLACE FUNCTION authz.create_api_key(p_name text, p_scopes text DEFAULT '', p_expires_at timestamptz DEFAULT NULL,
  p_principal_type text DEFAULT NULL, p_principal_id text DEFAULT NULL)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_token text := 'ak_' || replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
        v_scopes text[] := ARRAY(SELECT DISTINCT btrim(x) FROM unnest(string_to_array(coalesce(p_scopes, ''), ',')) x
                                 WHERE btrim(x) <> '' ORDER BY 1);
        v_cur text[] := authz_int.scopes_active(); v_bad text;
        v_type text := coalesce(p_principal_type, 'user'); v_id text;
BEGIN
  PERFORM authz_int.check_writable();
  -- the principal's row is locked (FOR KEY SHARE) before it is checked: a delete of it waits for this key, or this
  -- for the delete, which leaves no principal to make it for (a delete with an older snapshot: keys_gone)
  IF p_principal_id IS NULL THEN
    v_id := authz.uid()::text;
    IF v_type <> 'user' OR v_id IS NULL OR NOT authz_int.hold('user', v_id) THEN
      RAISE EXCEPTION 'sign in to create an API key' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ714';
    END IF;
  ELSE
    v_id := authz_int.canon(v_type, p_principal_id);
    PERFORM authz_int.hold(v_type, v_id);
    PERFORM authz_int.check_manage_keys(v_type, v_id);
  END IF;
  SELECT string_agg(x, ', ') INTO v_bad FROM unnest(v_scopes) x
  WHERE NOT EXISTS (SELECT 1 FROM authz_int.scope_items WHERE scope = x);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'no scope % in the policy', v_bad USING HINT = 'rowstile help AZ707'; END IF;
  IF v_cur IS NOT NULL AND (cardinality(v_scopes) = 0 OR NOT v_scopes <@ v_cur) THEN
    RAISE EXCEPTION 'a key cannot have more scopes than the session creating it' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ704';
  END IF;
  INSERT INTO authz.api_keys (user_id, principal_type, name, prefix, hash, scopes, expires_at)
  VALUES (v_id, v_type, p_name, left(v_token, 10), encode(sha256(convert_to(v_token, 'UTF8')), 'hex'),
          array_to_string(v_scopes, ','), p_expires_at);
  PERFORM authz_int.mark_row(v_type, v_id);
  PERFORM authz_int.audit('create_api_key', v_type, v_id, NULL, NULL, NULL, NULL,
                          jsonb_build_object('name', p_name, 'scopes', v_scopes, 'expires_at', p_expires_at));
  RETURN v_token;
END $f$;

-- the API keys of user rows that are gone, or whose id changed, are deleted (authz_int.keys_gone)
CREATE FUNCTION authz_int."user__keys_gone"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF TG_OP = 'TRUNCATE' THEN
    PERFORM authz_int.keys_gone('user', NULL);
  ELSIF TG_OP = 'UPDATE' THEN   -- on a partitioned table (the last trigger below): the ids the update left no row with
    PERFORM authz_int.keys_gone('user', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
  ELSE
    PERFORM authz_int.keys_gone('user', ARRAY(SELECT o."id"::text FROM old_rows o));
  END IF;
  RETURN NULL;
END $f$;

CREATE FUNCTION authz_int."user__keys_gone_id"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  PERFORM authz_int.keys_gone('user', ARRAY[OLD."id"::text]);
  RETURN NULL;
END $f$;

-- before TRUNCATE empties the table: with a snapshot older than a key made for one of its rows, fail to serialize
CREATE FUNCTION authz_int."user__keys_gone_all"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF pg_catalog.current_setting('transaction_isolation') <> 'read committed' THEN
    PERFORM authz_int.keys_gone('user', ARRAY(SELECT x."id"::text FROM "ms"."users" x));
  END IF;
  RETURN NULL;
END $f$;

CREATE TRIGGER "authz_user_keys_gone_del" AFTER DELETE ON "ms"."users"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__keys_gone"();

CREATE TRIGGER "authz_user_keys_gone_id" AFTER UPDATE ON "ms"."users" FOR EACH ROW
  WHEN (OLD."id" IS DISTINCT FROM NEW."id") EXECUTE FUNCTION authz_int."user__keys_gone_id"();

CREATE TRIGGER "authz_user_keys_gone_trunc" AFTER TRUNCATE ON "ms"."users"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__keys_gone"();

CREATE TRIGGER "authz_user_keys_gone_trunc_first" BEFORE TRUNCATE ON "ms"."users"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__keys_gone_all"();

-- On a partitioned table, an update that puts a row in another partition is a delete there and an insert here:
-- Postgres runs no AFTER UPDATE row trigger for it. The ids an update leaves no row with lose their keys too.
-- @object trigger "authz_user_keys_gone_moved" ON "ms"."users"
-- @if partitioned
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_catalog.pg_class WHERE oid = '"ms"."users"'::regclass) = 'p' THEN
    EXECUTE 'CREATE TRIGGER "authz_user_keys_gone_moved" AFTER UPDATE ON "ms"."users" REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__keys_gone"()';
  END IF;
END $tr$;

